@php
    $flightKeys = collect($tables)->flatMap(fn ($table) => $table['rows']->items())->pluck('id')->filter();
    $infrastructureLinks = \Illuminate\Support\Facades\DB::connection('ops')->table('resource_allocations as a')->join('airport_resources as r','r.id','=','a.resource_id')->join('flights as f','f.id','=','a.flight_id')->leftJoin('airport_infrastructure as i','i.id','=','r.infrastructure_id')->whereIn('a.flight_id',$flightKeys)->orderBy('a.starts_at')->limit(50)->get(['f.number','f.origin','f.destination','r.code','r.type','i.name','a.starts_at','a.ends_at']);
@endphp
<section class="airport-card mb-4"><h2>Hạ tầng theo các phân bổ đã lưu</h2><div class="table-responsive"><table class="table airport-table"><thead><tr><th>Chuyến / sân bay</th><th>Hạ tầng</th><th>Bắt đầu</th><th>Kết thúc</th></tr></thead><tbody>@forelse($infrastructureLinks as $link)<tr><td>{{ $link->number }} · {{ $link->origin }} → {{ $link->destination }}</td><td>{{ \App\Support\InfrastructureDisplay::name($link) }}</td><td>{{ \App\Support\Ui::date($link->starts_at) }}</td><td>{{ \App\Support\Ui::date($link->ends_at) }}</td></tr>@empty<tr><td colspan="4" class="subtle">Chưa có phân bổ được lưu cho các chuyến đang hiển thị.</td></tr>@endforelse</tbody></table></div><p class="subtle">Tối đa 50 lượt phân bổ theo danh sách chuyến đang xem; thời gian theo giờ Việt Nam. Không tự gán đường băng.</p></section>
